const searchProjects = `-- name: SearchProjects :many
SELECT id, slug, title, description, body, project_type, client_side, server_side, status, downloads, follows, loaders, game_versions, categories, published_at, team_id, license, icon_key, meta_flags
FROM projects
WHERE ($1::text = '' OR title ILIKE '%' || $1::text || '%' OR description ILIKE '%' || $1::text || '%')
  AND (cardinality($2::text[]) = 0 OR loaders && $2::text[])
  AND (cardinality($3::text[]) = 0 OR game_versions && $3::text[])
  AND (cardinality($4::text[]) = 0 OR project_type = ANY($4::text[]))
  AND (cardinality($5::text[]) = 0 OR categories && $5::text[])
  AND ($6::text = '' OR status = $6::text)
ORDER BY downloads DESC, created_at DESC
LIMIT $7 OFFSET $8
`

type SearchProjectsParams struct {
	Column1 string
	Column2 []string
	Column3 []string
	Column4 []string
	Column5 []string
	Column6 string
	Limit   int32
	Offset  int32
}

type SearchProjectsRow struct {
	ID           string
	Slug         string
	Title        string
	Description  string
	Body         string
	ProjectType  string
	ClientSide   string
	ServerSide   string
	Status       string
	Downloads    int64
	Follows      int64
	Loaders      []string
	GameVersions []string
	Categories   []string
	PublishedAt  pgtype.Timestamptz
	TeamID       pgtype.Text
	License      string
	IconKey      string
	MetaFlags    []string
}

func (q *Queries) SearchProjects(ctx context.Context, arg SearchProjectsParams) ([]SearchProjectsRow, error) {
	rows, err := q.db.Query(ctx, searchProjects,
		arg.Column1,
		arg.Column2,
		arg.Column3,
		arg.Column4,
		arg.Column5,
		arg.Column6,
		arg.Limit,
		arg.Offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchProjectsRow
	for rows.Next() {
		var i SearchProjectsRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Title,
			&i.Description,
			&i.Body,
			&i.ProjectType,
			&i.ClientSide,
			&i.ServerSide,
			&i.Status,
			&i.Downloads,
			&i.Follows,
			&i.Loaders,
			&i.GameVersions,
			&i.Categories,
			&i.PublishedAt,
			&i.TeamID,
			&i.License,
			&i.IconKey,
			&i.MetaFlags,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

